return ['domain'=>'itour-core','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','language'=>'ar','project-id-version'=>'itour-core','pot-creation-date'=>'2026-11-10T23:05:58+00:00','po-revision-date'=>'2026-11-10T23:05:58+00:00','messages'=>['Foundation for the iTourTMS modules: company settings, module registry, database migrations and shared services. Install this first, then add the modules you need.'=>'أساس وحدات iTourTMS: إعدادات الشركة وسجل الوحدات وتحديثات قاعدة البيانات والخدمات المشتركة. ثبّت هذه الإضافة أولًا، ثم أضف الوحدات التي تحتاجها.','Booking widget: activate iTour Tour Packages, Excursions or Transfers to add their searches here.'=>'أداة الحجز: فعّل إضافة الباقات السياحية أو الرحلات اليومية أو التنقلات لتظهر خانات البحث الخاصة بها هنا.','Where to next?'=>'إلى أين وجهتك القادمة؟','What are you looking for?'=>'ما الذي تبحث عنه؟','Looking for'=>'أبحث عن','Search'=>'بحث','My account'=>'حسابي','Sign in'=>'تسجيل الدخول','Signing in…'=>'جارٍ تسجيل الدخول…','Creating your account…'=>'جارٍ إنشاء حسابك…','No connection. Check your internet and try again.'=>'لا يوجد اتصال. تحقق من الإنترنت وحاول مرة أخرى.','Show password'=>'إظهار كلمة المرور','Close'=>'إغلاق','Sign up'=>'إنشاء حساب','Email or username'=>'البريد الإلكتروني أو اسم المستخدم','Password'=>'كلمة المرور','Keep me signed in'=>'تذكرني','Forgot password?'=>'نسيت كلمة المرور؟','Full name'=>'الاسم الكامل','Email'=>'البريد الإلكتروني','At least 8 characters.'=>'8 أحرف على الأقل.','Create account'=>'إنشاء الحساب','Enter your email or username and your password.'=>'أدخل بريدك الإلكتروني أو اسم المستخدم وكلمة المرور.','New accounts are closed on this site.'=>'إنشاء حسابات جديدة متوقف في هذا الموقع.','Enter your name and a valid email address.'=>'أدخل اسمك وبريدًا إلكترونيًا صحيحًا.','Choose a password of at least 8 characters.'=>'اختر كلمة مرور من 8 أحرف على الأقل.','This email already has an account. Sign in instead, or reset your password.'=>'هذا البريد له حساب بالفعل. سجّل الدخول، أو أعد تعيين كلمة المرور.','%1$s, line %2$d: “%3$s” isn’t valid here.'=>'%1$s، السطر %2$d: «%3$s» غير صالح هنا.','Cancellation'=>'الإلغاء','One tier per line: Days before arrival | Fee % | Travel from | Travel to (dates optional, for a season tier). Example: 30 | 0 then 14 | 50 then 0 | 100.'=>'شريحة في كل سطر: أيام قبل الوصول | الرسوم % | السفر من | السفر إلى (التواريخ اختيارية، لشريحة موسمية). مثال: 30 | 0 ثم 14 | 50 ثم 0 | 100.','Included'=>'يشمل','One item per line.'=>'بند في كل سطر.','Not included'=>'لا يشمل','FAQ'=>'الأسئلة الشائعة','One question per line: Question | Answer.'=>'سؤال في كل سطر: السؤال | الإجابة.','Empty for a new product. Keep the number from an export to update that product.'=>'فارغ لمنتج جديد. احتفظ بالرقم من التصدير لتحديث ذلك المنتج.','Title'=>'العنوان','Required for new products.'=>'مطلوب للمنتجات الجديدة.','Status'=>'الحالة','publish or draft. New products are drafts unless you write publish.'=>'publish أو draft. المنتجات الجديدة مسودات ما لم تكتب publish.','Summary'=>'الملخص','One or two sentences, shown in lists.'=>'جملة أو جملتان تظهر في القوائم.','Description'=>'الوصف','The page text. Leave a blank line between paragraphs.'=>'نص الصفحة. اترك سطرًا فارغًا بين الفقرات.','Categories'=>'التصنيفات','Comma separated. New names are created.'=>'مفصولة بفواصل. الأسماء الجديدة تُنشأ.','Languages'=>'اللغات','Comma separated, e.g. English, German.'=>'مفصولة بفواصل، مثل English, German.','Suitable for'=>'مناسبة لـ','Comma separated, e.g. Families, Couples.'=>'مفصولة بفواصل، مثل Families, Couples.','ID %d is not one of these products. Leave ID empty to create a new one.'=>'المعرف %d ليس من هذه المنتجات. اترك ID فارغًا لإنشاء منتج جديد.','Title is required for a new product.'=>'العنوان مطلوب للمنتج الجديد.','Status must be publish or draft.'=>'الحالة يجب أن تكون publish أو draft.','“%s” is already used.'=>'«%s» مستخدم بالفعل.','Not found'=>'غير موجود','Back to the list'=>'العودة إلى القائمة','Add %s'=>'إضافة %s','View %s'=>'عرض %s','Edit %s'=>'تعديل %s','Please fix the highlighted fields.'=>'يُرجى تصحيح الحقول المحددة.','Save'=>'حفظ','Add new'=>'إضافة جديد','Saved.'=>'تم الحفظ.','Deleted.'=>'تم الحذف.','Not deleted: move or delete the items under it first.'=>'لم يُحذف: انقل العناصر التي تحته أو احذفها أولًا.','Nothing matches that search.'=>'لا توجد نتائج مطابقة لهذا البحث.','Nothing here yet. Use “Add new” to create the first one.'=>'لا يوجد شيء هنا بعد. استخدم «إضافة جديد» لإنشاء أول عنصر.','View'=>'عرض','Edit'=>'تعديل','Delete this permanently?'=>'حذف هذا نهائيًا؟','Delete'=>'حذف','Yes'=>'نعم','— None —'=>'— لا شيء —','%s has an invalid value.'=>'قيمة «%s» غير صحيحة.','%s is required.'=>'«%s» مطلوب.','Column'=>'العمود','What to write'=>'ما يُكتب','Rules'=>'القواعد','One product per row. Leave ID empty to create a new product; keep the ID to update that product. When updating, an empty cell keeps what is saved; write - (a dash) to clear it. Cells marked "one per line" take one entry per line (Alt+Enter in Excel) with the parts separated by | in the order given. Images are not imported: add them on each product afterwards.'=>'منتج واحد في كل صف. اترك ID فارغًا لإنشاء منتج جديد؛ احتفظ بالـ ID لتحديث ذلك المنتج. عند التحديث، الخلية الفارغة تُبقي المحفوظ؛ اكتب - (شرطة) لمسحه. الخلايا المكتوب عليها «واحد في كل سطر» تأخذ إدخالًا في كل سطر (Alt+Enter في Excel) والأجزاء مفصولة بـ | بالترتيب المذكور. الصور لا تُستورد: أضفها لكل منتج بعد ذلك.','Instructions'=>'التعليمات','Import / export: %s'=>'استيراد / تصدير: %s','That file couldn’t be read. Upload the .xlsx you downloaded here (Excel: File → Save As → Excel Workbook).'=>'تعذرت قراءة الملف. ارفع ملف ‎.xlsx الذي نزّلته من هنا (في Excel: ملف ← حفظ باسم ← مصنف Excel).','The file has no rows under the header.'=>'لا توجد صفوف تحت صف العناوين في الملف.','The checked file expired. Upload it again.'=>'انتهت صلاحية الملف المفحوص. ارفعه مرة أخرى.','This server can’t read or write Excel files (the PHP zip extension is missing). Ask 